#include <cstdio>

struct V3 { float X, Y, Z; V3(float x, float y, float z) : X(x), Y(y), Z(z) { } };
struct Thing { V3 Pos; long Map; Thing(float x, long map) : Pos(x, 0, 0), Map(map) { } };
